    story.append(ls_table)
    story.append(Spacer(1, 10))

    # ── REBA ──────────────────────────────────────────────────────────────────
    story.append(Paragraph('3. RESULTADOS MÉTODO REBA', h2_style))
    reba = ev.get('reba_data', {})
    reba_score = ev.get('reba_score', 0)
