def login_required(f):
    @wraps(f)
    def dec(*a, **kw):
        if 'user_id' not in session: return redirect(url_for('login'))
        return f(*a, **kw)
    return dec

@app.route('/')
def index():
    return redirect(url_for('dashboard' if 'user_id' in session else 'login'))

@app.route('/login', methods=['GET','POST'])
def login():
    error = None
    if request.method == 'POST':
        u = request.form.get('username','').strip()
        p = request.form.get('password','').strip()
        if not rate_limit(f'login_{request.remote_addr}'):
            error = 'Demasiados intentos.'
        else:
            db = get_db()
            user = db.execute('SELECT * FROM users WHERE username=?', (u,)).fetchone()
            db.close()
            if user and check_password_hash(user['password_hash'], p):
                session.permanent = True
                session['user_id'] = user['id']
                session['username'] = user['username']
                session['empresa'] = user['empresa']
                session['evaluador'] = user['evaluador']
                session['role'] = user['role']
                return redirect(url_for('dashboard'))
            error = 'Usuario o contrasena incorrectos'
    return render('login.html', error=error)

@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('login'))

@app.route('/register', methods=['GET','POST'])
def register():
    error = success = None
    if request.method == 'POST':
        code = request.form.get('access_code','').strip()
        u = request.form.get('username','').strip()
        p = request.form.get('password','').strip()
        emp = request.form.get('empresa','').strip()
        ev = request.form.get('evaluador','').strip()
        if code != MASTER_REGISTRATION_CODE: error = 'Codigo invalido.'
        elif not u or not p: error = 'Usuario y contrasena requeridos'
        elif len(p) < 6: error = 'Contrasena min 6 caracteres'
        else:
            db = get_db()
            try:
                db.execute("INSERT INTO users (username,password_hash,empresa,evaluador) VALUES (?,?,?,?)",
                           (u, generate_password_hash(p), emp, ev))
                db.commit(); success = 'Cuenta creada.'
            except sqlite3.IntegrityError: error = 'Usuario ya existe'
            finally: db.close()
    return render('register.html', error=error, success=success)

@app.route('/dashboard')
@login_required
def dashboard():
    db = get_db()
    is_admin = session.get('role') == 'director'
    if is_admin:
        evals = db.execute('SELECT e.*, u.username as evaluador_nombre FROM evaluaciones e LEFT JOIN users u ON e.user_id=u.id ORDER BY e.created_at DESC LIMIT 20').fetchall()
        stats = db.execute("SELECT COUNT(*) as total, SUM(CASE WHEN nivel_riesgo_ley_silla='BAJO' THEN 1 ELSE 0 END) as bajo, SUM(CASE WHEN nivel_riesgo_ley_silla='MEDIO' THEN 1 ELSE 0 END) as medio, SUM(CASE WHEN nivel_riesgo_ley_silla='ALTO' THEN 1 ELSE 0 END) as alto FROM evaluaciones").fetchone()
        razones = db.execute('SELECT DISTINCT razon_social FROM evaluaciones WHERE razon_social IS NOT NULL ORDER BY razon_social').fetchall()
    else:
        evals = db.execute('SELECT * FROM evaluaciones WHERE user_id=? ORDER BY created_at DESC LIMIT 20', (session['user_id'],)).fetchall()
        stats = db.execute("SELECT COUNT(*) as total, SUM(CASE WHEN nivel_riesgo_ley_silla='BAJO' THEN 1 ELSE 0 END) as bajo, SUM(CASE WHEN nivel_riesgo_ley_silla='MEDIO' THEN 1 ELSE 0 END) as medio, SUM(CASE WHEN nivel_riesgo_ley_silla='ALTO' THEN 1 ELSE 0 END) as alto FROM evaluaciones WHERE user_id=?", (session['user_id'],)).fetchone()
        razones = db.execute('SELECT DISTINCT razon_social FROM evaluaciones WHERE user_id=? AND razon_social IS NOT NULL', (session['user_id'],)).fetchall()
    db.close()
    return render('dashboard.html', evaluaciones=evals, stats=stats, razones=razones)

