@app.route('/nueva-evaluacion')
@login_required
def nueva_evaluacion():
    tipo_eval = request.args.get('tipo', 'ley_silla')  # Por defecto Ley Silla
    if tipo_eval not in ['ley_silla', 'nom_036']:
        return redirect(url_for('seleccionar_tipo_evaluacion'))
    
    db = get_db()
    razones = db.execute('SELECT DISTINCT razon_social FROM evaluaciones WHERE user_id=? AND razon_social IS NOT NULL', (session['user_id'],)).fetchall()
    trabajadores = db.execute('SELECT * FROM trabajadores WHERE user_id=? ORDER BY nombre', (session['user_id'],)).fetchall()
    # Also get distinct areas and puestos
    areas = db.execute('SELECT DISTINCT area FROM trabajadores WHERE user_id=? AND area IS NOT NULL AND area != "" ORDER BY area', (session['user_id'],)).fetchall()
    puestos = db.execute('SELECT DISTINCT puesto FROM trabajadores WHERE user_id=? AND puesto IS NOT NULL AND puesto != "" ORDER BY puesto', (session['user_id'],)).fetchall()
    db.close()
    return render('evaluacion.html', tipo_evaluacion=tipo_eval, razones=razones, trabajadores=[dict(t) for t in trabajadores], areas=[dict(a) for a in areas], puestos=[dict(p) for p in puestos])

