@app.route('/historial')
@login_required
def historial():
    filtro = request.args.get('razon_social', '')
    db = get_db()
    is_admin = session.get('role') == 'director'
    if is_admin:
        if filtro:
            evals = db.execute('SELECT e.*, u.username as evaluador_nombre FROM evaluaciones e LEFT JOIN users u ON e.user_id=u.id WHERE e.razon_social=? ORDER BY e.created_at DESC', (filtro,)).fetchall()
        else:
            evals = db.execute('SELECT e.*, u.username as evaluador_nombre FROM evaluaciones e LEFT JOIN users u ON e.user_id=u.id ORDER BY e.created_at DESC').fetchall()
        razones = db.execute('SELECT DISTINCT razon_social FROM evaluaciones WHERE razon_social IS NOT NULL ORDER BY razon_social').fetchall()
    else:
        if filtro:
            evals = db.execute('SELECT * FROM evaluaciones WHERE user_id=? AND razon_social=? ORDER BY created_at DESC', (session['user_id'], filtro)).fetchall()
        else:
            evals = db.execute('SELECT * FROM evaluaciones WHERE user_id=? ORDER BY created_at DESC', (session['user_id'],)).fetchall()
        razones = db.execute('SELECT DISTINCT razon_social FROM evaluaciones WHERE user_id=? AND razon_social IS NOT NULL', (session['user_id'],)).fetchall()
    db.close()
    return render('historial.html', evaluaciones=evals, razones=razones, filtro_actual=filtro)

