@app.route('/api/admin/delete-user/<int:uid>', methods=['POST'])
@admin_required
def admin_delete_user(uid):
    if uid == session.get('user_id'):
        return jsonify({'error': 'No puede eliminarse a sí mismo'}), 400
    db = get_db()
    db.execute('DELETE FROM users WHERE id=?', (uid,))
    db.commit(); db.close()
    return jsonify({'success': True})

@app.route('/api/admin/create-user', methods=['POST'])
@admin_required
def admin_create_user():
    data = request.get_json()
    if not data.get('username') or not data.get('password'):
        return jsonify({'error': 'Usuario y contraseña requeridos'}), 400
    db = get_db()
    try:
        db.execute('INSERT INTO users (username,password_hash,empresa,evaluador,role) VALUES (?,?,?,?,?)',
                   (data['username'], generate_password_hash(data['password']),
                    data.get('empresa',''), data.get('evaluador',''), data.get('role','evaluador')))
        db.commit()
        return jsonify({'success': True})
    except sqlite3.IntegrityError:
        return jsonify({'error': 'El usuario ya existe'}), 400
    finally:
        db.close()

@app.route('/api/report/<eu>/<fmt>')
@login_required
def gen_report(eu, fmt):
    db = get_db()
    if session.get('role') == 'director':
        ev = db.execute('SELECT * FROM evaluaciones WHERE uuid=?', (eu,)).fetchone()
    else:
        ev = db.execute('SELECT * FROM evaluaciones WHERE uuid=? AND user_id=?', (eu, session['user_id'])).fetchone()
    db.close()
    if not ev: return jsonify({'error': 'Not found'}), 404
    d = dict(ev); d['evaluador'] = session.get('evaluador','')
    for f in ['reba_data','lest_data','ley_silla_data','angulos_data','recomendaciones','capturas_json']:
        if d.get(f):
            try: d[f] = json.loads(d[f])
            except: pass
    if fmt == 'pdf': return send_file(generate_pdf(d), as_attachment=True, download_name=f"eval_{eu[:8]}.pdf")
    elif fmt == 'docx': return send_file(generate_docx(d), as_attachment=True, download_name=f"eval_{eu[:8]}.docx")
    elif fmt == 'xlsx': return send_file(generate_xlsx(d), as_attachment=True, download_name=f"eval_{eu[:8]}.xlsx")
    return jsonify({'error': 'Bad format'}), 400

